# app/routers/trade_share.py
#
# Backs the Portfolio "Share" button: a branded PNG of one completed
# trade, generated by the same headless-Chromium render pipeline already
# used for player card art (see player_card_render.py's module docstring
# for why an internal render-data endpoint + hidden frontend route is
# the pattern, rather than rendering server-side with e.g. Pillow).
from __future__ import annotations

import logging
from typing import Any, Dict

from fastapi import APIRouter, Depends, HTTPException, Query, Request

from app.auth.entitlements import compute_entitlements
from app.services.trade_share_data import (
    build_share_caption,
    build_trade_share_render_data,
    get_owned_trade,
)
from app.services.trade_share_token import verify_render_token

log = logging.getLogger("trade_share")

internal_router = APIRouter(prefix="/api/internal", tags=["internal-render"])
router = APIRouter(prefix="/api/trades", tags=["Trades"])


@internal_router.get("/render/trade-share/{trade_id}")
async def get_trade_share_render_data(trade_id: int, token: str = Query(...)) -> Dict[str, Any]:
    user_id = verify_render_token(trade_id, token)
    if not user_id:
        raise HTTPException(status_code=403, detail="Invalid or expired render token")

    trade = await get_owned_trade(user_id, trade_id)
    if trade is None:
        raise HTTPException(status_code=404, detail="Trade not found")

    return {"data": await build_trade_share_render_data(trade)}


@router.post("/{trade_id}/share-card")
async def create_trade_share_card(trade_id: int, request: Request):
    ent = await compute_entitlements(request)
    user_id = ent.get("user_id")
    if not user_id:
        raise HTTPException(status_code=401, detail="Not authenticated")

    trade = await get_owned_trade(str(user_id), trade_id)
    if trade is None:
        raise HTTPException(status_code=404, detail="Trade not found")

    from app.services.trade_share_render import TradeShareRenderError, render_trade_share_png

    render_data = await build_trade_share_render_data(trade)
    try:
        rendered = await render_trade_share_png(str(user_id), trade_id)
    except TradeShareRenderError:
        log.warning("Trade share render failed for trade_id=%s", trade_id, exc_info=True)
        raise HTTPException(status_code=502, detail="Couldn't generate the share image - please try again.")

    import base64

    return {
        "image_data_url": f"data:image/png;base64,{base64.b64encode(rendered.png_bytes).decode('ascii')}",
        "caption": build_share_caption(render_data),
    }
